import argparse
import json
import csv

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)

    path = payload["path"]

    total = 0.0
    with open(path, 'r') as f:
        reader = csv.reader(f)
        rows = [row for row in reader if any(cell.strip() for cell in row)]

        amount_col = None
        start_idx = 0

        if rows:
            header = rows[0]
            for i, col in enumerate(header):
                if col.strip().lower() == 'amount':
                    amount_col = i
                    start_idx = 1
                    break

        for row in rows[start_idx:]:
            if amount_col is None:
                col_idx = len(row) - 1
            else:
                col_idx = amount_col

            if col_idx >= len(row):
                continue

            amount_str = row[col_idx].strip()
            amount_str = amount_str.replace('$', '').replace(',', '')
            if not amount_str:
                continue
            try:
                total += float(amount_str)
            except ValueError:
                continue

    print(f"{total:.2f}")

if __name__ == "__main__":
    main()

import argparse
import json


def parse_time(s):
    parts = s.split(':')
    if len(parts) != 3:
        return None
    try:
        h, m, sec = int(parts[0]), int(parts[1]), int(parts[2])
        return h * 3600 + m * 60 + sec
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    lower = 8 * 3600          # 08:00:00
    upper = 8 * 3600 + 30 * 60  # 08:30:00

    count = 0
    with open(path, 'r') as f:
        for line in f:
            fields = line.split()
            if len(fields) < 2:
                continue
            if fields[1] != 'ERROR':
                continue
            t = parse_time(fields[0])
            if t is None:
                continue
            if lower <= t < upper:
                count += 1

    print(count)


if __name__ == "__main__":
    main()

import argparse
import csv
import json


def parse_amount(s):
    s = s.strip()
    if not s:
        return 0.0
    s = s.replace('$', '').replace(',', '')
    if s.startswith('-'):
        return -float(s[1:])
    return float(s)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    total = 0.0
    with open(path, 'r', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            amount_str = row.get("amount", "")
            if amount_str is None:
                continue
            amount_str = amount_str.strip()
            if not amount_str:
                continue
            total += parse_amount(amount_str)

    print(f"{total:.2f}")


if __name__ == "__main__":
    main()

import argparse
import csv
import json


def parse_amount(s):
    s = s.strip()
    if not s:
        return None
    if s.startswith('$'):
        s = s[1:]
    s = s.replace(',', '')
    if s.startswith('-'):
        return -float(s[1:])
    return float(s)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)

    path = payload["path"]

    total = 0.0
    with open(path, 'r', newline='') as f:
        reader = csv.reader(f)
        rows = list(reader)

    if not rows:
        print("0.00")
        return

    header = rows[0]
    amount_col = -1
    for i, h in enumerate(header):
        if 'amount' in h.lower():
            amount_col = i
            break

    if amount_col >= 0:
        data_rows = rows[1:]
    else:
        amount_col = len(header) - 1
        data_rows = rows

    for row in data_rows:
        if not row or not any(cell.strip() for cell in row):
            continue
        if amount_col >= len(row):
            continue
        val = parse_amount(row[amount_col])
        if val is not None:
            total += val

    print(f"{total:.2f}")


if __name__ == "__main__":
    main()

import argparse
import json


def parse_amount(s):
    s = s.strip()
    if not s:
        return None
    sign = 1
    if s.startswith('-'):
        sign = -1
        s = s[1:]
    elif s.startswith('+'):
        s = s[1:]
    if s.startswith('$'):
        s = s[1:]
    s = s.replace(',', '')
    try:
        return sign * float(s)
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    total = 0.0
    with open(path, 'r') as f:
        for line in f:
            amt = parse_amount(line)
            if amt is not None:
                total += amt

    print(f"{total:.2f}")


if __name__ == "__main__":
    main()

import argparse
import json


def parse_time(s):
    parts = s.split(":")
    return int(parts[0]) * 3600 + int(parts[1]) * 60 + int(parts[2])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    count = 0
    with open(path, "r") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line:
                continue
            parts = line.split(" ", 2)
            if len(parts) < 3:
                continue
            timestamp, level, _ = parts
            if level != "ERROR":
                continue
            try:
                t = parse_time(timestamp)
            except (ValueError, IndexError):
                continue
            if 28800 <= t < 30600:
                count += 1

    print(count)


if __name__ == "__main__":
    main()

import argparse
import csv
import json
from datetime import date


def parse_date(cell):
    cell = cell.strip()
    if len(cell) != 10:
        return None
    if cell[4] != "-" or cell[7] != "-":
        return None
    try:
        y = int(cell[0:4])
        m = int(cell[5:7])
        d = int(cell[8:10])
        return date(y, m, d)
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    dates = []
    with open(path, "r", newline="") as f:
        reader = csv.reader(f)
        for row in reader:
            for cell in row:
                d = parse_date(cell)
                if d is not None:
                    dates.append(d)

    if len(dates) < 2:
        print(0)
        return

    diff = (max(dates) - min(dates)).days
    print(diff)


if __name__ == "__main__":
    main()

import argparse
import csv
import json
from datetime import date


def parse_date(s):
    s = s.strip()
    parts = s.split("-")
    if len(parts) != 3:
        return None
    try:
        return date(int(parts[0]), int(parts[1]), int(parts[2]))
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    dates = []
    with open(path, "r", newline="") as f:
        reader = csv.reader(f)
        for row in reader:
            if not row:
                continue
            for cell in row:
                d = parse_date(cell)
                if d is not None:
                    dates.append(d)
                    break

    if len(dates) < 2:
        print(0)
        return

    diff = (max(dates) - min(dates)).days
    print(diff)


if __name__ == "__main__":
    main()
